def rate_feedback(geheim, tipps):
    rueckmeldungen = []
    for tipp in tipps:
        if tipp < geheim:
            rueckmeldungen.append("Zu klein!")
        elif tipp > geheim:
            rueckmeldungen.append("Zu gross!")
        else:
            rueckmeldungen.append("Richtig! Die geheime Zahl war " + str(geheim) + ".")
            break
    return rueckmeldungen

