def alle_paarungen(symbols, verbs):
    ergebnis = []
    zaehler = 0
    for i in range(len(symbols)):
        for j in range(i + 1, len(symbols)):
            ergebnis.append(symbols[i] + " " + verbs[zaehler] + " " + symbols[j])
            zaehler = zaehler + 1
    return ergebnis

