    for zeile in range(hoehe):
        text = ""
        for spalte in range(breite):
            if zeile == 0 or zeile == hoehe - 1 or spalte == 0 or spalte == breite - 1:
                text = text + "*"
            else:
                text = text + " "
        zeilen.append(text)
    return zeilen

