def runde_auswerten(wuerfe, grenze):
    punkte = 0
    anzahl = 0
    for wurf in wuerfe:
        anzahl = anzahl + 1
        if wurf == 1:
            return (0, anzahl)
        punkte = punkte + wurf
        if punkte >= grenze:
            break
    return (punkte, anzahl)

